import sys
import math
import heapq

def main():
    import sys
    import math
    import heapq

    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    bases = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(n)]

    origin = None
    points = []
    for x, y in bases:
        if x == 0 and y == 0:
            origin = (x, y)
        else:
            angle = math.atan2(y, x)
            dist = math.sqrt(x * x + y * y)
            points.append((angle, dist))

    points.sort()

    def get_distance(p1, p2):
        if p1[0] == p2[0]:
            return abs(p1[1] - p2[1])
        else:
            return p1[1] + p2[1]

    max_heap = []
    for i in range(n - 1):
        for j in range(i + 1, n):
            if points[i][0] == points[j][0]:
                continue
            dist = get_distance(points[i], points[j])
            heapq.heappush(max_heap, -dist)

    selected_points = set()
    while len(selected_points) < k - 1:
        while max_heap and points.index(min(points, key=lambda p: p[0])) in selected_points:
            heapq.heappop(max_heap)
        if max_heap:
            dist = -heapq.heappop(max_heap)
            for i, p in enumerate(points):
                if p[0] == min(points, key=lambda p: p[0])[0]:
                    selected_points.add(i)
                    break

    total_distance = 0
    selected_points = sorted(selected_points)
    for i in range(len(selected_points)):
        for j in range(i + 1, len(selected_points)):
            total_distance += get_distance(points[selected_points[i]], points[selected_points[j]])

    for i in range(len(selected_points)):
        for j in range(len(points)):
            if j not in selected_points:
                total_distance += points[j][1]

    print(f"{total_distance:.10f}")

main()
